//! 🧪️ The actual terminal handoff preserves its Source and recorded receipt through unwind.
use semio_framework_value_native_decode_handoff::{NativeDecodeFrameHandoff,NativeDecodeFrameTerminalOutput,NativeTerminalFailureOutput};
use semio_framework_value_native_decoding::{NativeDecodeControl,NativeDecodeFrame,NativeDecodeRetirementRecipient};
use semio_framework_value_control_contract::*;
#[path="../../🏭️construction/🧪️tests/source-bank.rs"] mod source_bank;
#[path="retirement.rs"] mod retirement_actor;
#[path="driver.rs"] mod driver;
use driver::PaidAction;
#[test]
fn same_source_handoff_recovers_recorded_post_once(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🏭️construction/🧳️slots/🧪️tests/owner.json")).unwrap();let mut bank=source_bank::Bank::from_stock(&fixture["stock"],false);let mut observe=|_|true;let control=NativeDecodeControl::new(1<<20,&mut observe);let receipt=control.pause().unwrap_or_else(|_|panic!("original decoder admission"));let ledger=receipt.ledger_identity();let mut frame=NativeDecodeFrame::from_continuation(receipt);let mut recipient=NativeDecodeRetirementRecipient::new();bank.run_frame(&mut frame,Some(&mut recipient),&mut observe,|_,_|Ok(())).unwrap_or_else(|_|panic!("original Work binding"));let(mut frame,mut recipient)=(Some(frame),Some(recipient));let mut owner=NativeDecodeFrameTerminalOutput::default();let mut handoff=NativeDecodeFrameHandoff::default();let before=bank.wallet.lock().unwrap().fuel;let mut foreign=bank.sibling_authority();assert!(foreign.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut owner,&mut observe).is_err());assert!(frame.is_some()&&recipient.is_some()&&!owner.is_ready());assert_eq!(before-bank.wallet.lock().unwrap().fuel,0);bank.wallet.lock().unwrap().deny=true;assert!(!bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut owner,&mut observe).unwrap());assert!(frame.is_some()&&recipient.is_some()&&!owner.is_ready());assert_eq!(before-bank.wallet.lock().unwrap().fuel,0);bank.wallet.lock().unwrap().deny=false;bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut owner,&mut observe)));assert!(interrupted.is_err());assert!(frame.is_none()&&recipient.is_none()&&!owner.is_ready());assert_eq!(before-bank.wallet.lock().unwrap().fuel,1);let observed=bank.wallet.lock().unwrap().spent.copied_bytes;for _ in 0..16{if bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut owner,&mut observe).unwrap(){break}}assert!(owner.is_ready());assert_eq!(owner.ledger_identity(),Some(ledger));assert_eq!(bank.wallet.lock().unwrap().spent.copied_bytes,observed+NativeDecodeFrameHandoff::delivery_demand().copy_bytes);assert_eq!(before-bank.wallet.lock().unwrap().fuel,2);for _ in 0..16{if bank.retire_frame_output(&mut handoff,&mut owner,&mut observe).unwrap(){break}}assert!(!owner.is_ready());assert!(handoff.is_empty());assert_eq!(before-bank.wallet.lock().unwrap().fuel,3);
}

#[test]
fn original_frame_restores_nested_payout_from_both_real_owners(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🏭️construction/🧳️slots/🧪️tests/owner.json")).unwrap();let mut bank=source_bank::Bank::from_stock(&fixture["stock"],false);let mut foreign=bank.sibling_authority();let mut observe=|_|true;let control=NativeDecodeControl::new(1<<20,&mut observe);let receipt=control.pause().unwrap_or_else(|_|panic!("original decoder admission"));let ledger=receipt.ledger_identity();let mut frame=NativeDecodeFrame::from_continuation(receipt);let mut recipient=NativeDecodeRetirementRecipient::new();bank.run_frame(&mut frame,Some(&mut recipient),&mut observe,|_,_|Ok(())).unwrap_or_else(|_|panic!("original Work binding"));let before=bank.wallet.lock().unwrap().fuel;let original_error=ValueError::new(ValueRefusalKind::Canceled,String::from("original physical refusal"));let original_pointer=original_error.message.as_ptr();bank.wallet.lock().unwrap().post_error=Some(original_error);let mut first=PaidAction::default();first.begin(&mut bank,&mut frame,&mut recipient,None,RetirementDemand{copy_bytes:std::mem::size_of::<u64>(),depth:1,..Default::default()},&mut observe);let original_identity=first.physical.as_ref().unwrap().identity();let(mut source,mut output)=(Some(7),None);first.copy(&mut source,&mut output);assert_eq!(first.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Refused);first.finish_work(&mut bank,&mut frame,&mut recipient,&mut observe);assert_eq!(output,Some(7));
 let payout_error=ValueError::new(ValueRefusalKind::WorkLimit,String::from("separate payout refusal"));let payout_pointer=payout_error.message.as_ptr();bank.wallet.lock().unwrap().post_error=Some(payout_error);let mut capture=PaidAction::default();capture.begin(&mut bank,&mut frame,&mut recipient,Some(original_identity),OriginalConstructionCompletion::demand(),&mut observe);let rejected_identity=capture.physical.as_ref().unwrap().identity();let(mut original,mut refusal_unpublished,mut refusal,mut deep_refusal,mut retried)=(None,None,None,None,None);capture.capture(&mut bank,&mut first.physical,&mut original);bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||capture.post(&mut bank,&mut frame,&mut recipient,&mut observe)));assert!(interrupted.is_err());assert_eq!(capture.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Refused);capture.finish_work(&mut bank,&mut frame,&mut recipient,&mut observe);
 let nested_error=ValueError::new(ValueRefusalKind::OwnershipLimit,String::from("nested payout refusal"));let nested_pointer=nested_error.message.as_ptr();bank.wallet.lock().unwrap().post_error=Some(nested_error);let mut nested=PaidAction::default();nested.begin(&mut bank,&mut frame,&mut recipient,Some(rejected_identity),OriginalConstructionCompletion::demand(),&mut observe);let nested_identity=nested.physical.as_ref().unwrap().identity();nested.capture(&mut bank,&mut capture.physical,&mut refusal_unpublished);bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||nested.post(&mut bank,&mut frame,&mut recipient,&mut observe)));assert!(interrupted.is_err());assert_eq!(nested.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Refused);nested.finish_work(&mut bank,&mut frame,&mut recipient,&mut observe);let mut deep=PaidAction::default();deep.begin(&mut bank,&mut frame,&mut recipient,Some(nested_identity),OriginalConstructionCompletion::demand(),&mut observe);deep.capture(&mut bank,&mut nested.physical,&mut deep_refusal);assert_eq!(deep.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);deep.publish(&mut bank,&mut frame,&mut recipient,&mut deep_refusal,&mut observe);assert_eq!(deep_refusal.as_ref().unwrap().refusal().unwrap().message.as_ptr(),nested_pointer);deep.finish(&mut bank,&mut frame,&mut recipient,&mut observe);bank.with_terminal_loans(|work,physical|{let witness=physical.completion_retry_witness(refusal_unpublished.as_ref().unwrap(),deep_refusal.as_ref().unwrap())?.unwrap();frame.restore_terminal_completion_retry(&recipient,work,physical,&witness)}).unwrap();assert_eq!(frame.terminal_action_identity(),Some(rejected_identity));let mut retry_nested=PaidAction::default();retry_nested.begin(&mut bank,&mut frame,&mut recipient,Some(rejected_identity),OriginalConstructionCompletion::restage_demand(),&mut observe);retry_nested.restage(&mut bank,&mut refusal_unpublished,&mut refusal,deep_refusal.as_ref().unwrap());assert_eq!(retry_nested.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);retry_nested.publish(&mut bank,&mut frame,&mut recipient,&mut refusal,&mut observe);assert_eq!(refusal.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);retry_nested.finish(&mut bank,&mut frame,&mut recipient,&mut observe);
 bank.with_terminal_loans(|_,physical|{let witness=physical.completion_retry_witness(original.as_ref().unwrap(),refusal.as_ref().unwrap())?.unwrap();assert!(foreign.with_terminal_loans(|work,other|frame.restore_terminal_completion_retry(&recipient,work,other,&witness)).is_err());Ok(())}).unwrap();assert_eq!(frame.terminal_action_identity(),Some(rejected_identity));bank.with_terminal_loans(|work,physical|{let witness=physical.completion_retry_witness(original.as_ref().unwrap(),refusal.as_ref().unwrap())?.unwrap();frame.restore_terminal_completion_retry(&recipient,work,physical,&witness)}).unwrap();assert_eq!(frame.terminal_action_identity(),Some(original_identity));
 let mut retry=PaidAction::default();retry.begin(&mut bank,&mut frame,&mut recipient,Some(original_identity),OriginalConstructionCompletion::restage_demand(),&mut observe);retry.restage(&mut bank,&mut original,&mut retried,refusal.as_ref().unwrap());assert_eq!(retry.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);retry.publish(&mut bank,&mut frame,&mut recipient,&mut retried,&mut observe);assert_eq!(retried.as_ref().unwrap().refusal().unwrap().message.as_ptr(),original_pointer);assert_eq!(refusal.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);assert_eq!(deep_refusal.as_ref().unwrap().refusal().unwrap().message.as_ptr(),nested_pointer);retry.finish(&mut bank,&mut frame,&mut recipient,&mut observe);
 let mut release_deep=PaidAction::default();release_deep.begin(&mut bank,&mut frame,&mut recipient,Some(original_identity),deep_refusal.as_ref().unwrap().release_demand(),&mut observe);release_deep.retire(&mut bank,&mut frame,&mut deep_refusal,false);assert_eq!(release_deep.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release_deep.finish(&mut bank,&mut frame,&mut recipient,&mut observe);let mut release_refusal=PaidAction::default();release_refusal.begin(&mut bank,&mut frame,&mut recipient,Some(original_identity),refusal.as_ref().unwrap().release_demand(),&mut observe);release_refusal.retire(&mut bank,&mut frame,&mut refusal,false);assert_eq!(release_refusal.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release_refusal.finish(&mut bank,&mut frame,&mut recipient,&mut observe);let mut release_original=PaidAction::default();release_original.begin(&mut bank,&mut frame,&mut recipient,Some(original_identity),retried.as_ref().unwrap().release_demand(),&mut observe);release_original.retire(&mut bank,&mut frame,&mut retried,true);assert_eq!(release_original.post(&mut bank,&mut frame,&mut recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release_original.finish(&mut bank,&mut frame,&mut recipient,&mut observe);assert!(frame.terminal_action_identity().is_none());
 let(mut frame,mut recipient)=(Some(frame),Some(recipient));let mut terminal=NativeDecodeFrameTerminalOutput::default();let mut handoff=NativeDecodeFrameHandoff::default();for _ in 0..16{if bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut terminal,&mut observe).unwrap(){break}}assert_eq!(terminal.ledger_identity(),Some(ledger));for _ in 0..16{if bank.retire_frame_output(&mut handoff,&mut terminal,&mut observe).unwrap(){break}}assert!(handoff.is_empty());assert_eq!(before-bank.wallet.lock().unwrap().fuel,12);
}

#[test]
fn handoff_refusal_and_nested_payout_reach_same_bank_retirement(){
 let stock:serde_json::Value=serde_json::from_str(include_str!("failure-stock.json")).unwrap();let mut bank=source_bank::Bank::from_stock(&stock,false);let mut observe=|_|true;let control=NativeDecodeControl::new(1<<20,&mut observe);let receipt=control.pause().unwrap_or_else(|_|panic!("original decoder admission"));let ledger=receipt.ledger_identity();let mut frame=NativeDecodeFrame::from_continuation(receipt);let mut recipient=NativeDecodeRetirementRecipient::new();bank.run_frame(&mut frame,Some(&mut recipient),&mut observe,|_,_|Ok(())).unwrap_or_else(|_|panic!("original Work binding"));let(mut frame,mut recipient)=(Some(frame),Some(recipient));let mut terminal=NativeDecodeFrameTerminalOutput::default();let mut handoff=NativeDecodeFrameHandoff::default();let mut failure_slot=Some(NativeTerminalFailureOutput::default());let mut retirement=retirement_actor::Actor::new(&mut failure_slot);let work_error=ValueError::new(ValueRefusalKind::WorkLimit,String::from("original work refusal"));let work_pointer=work_error.message.as_ptr();let receipt_error=ValueError::new(ValueRefusalKind::Canceled,String::from("original physical refusal"));let receipt_pointer=receipt_error.message.as_ptr();let before=bank.wallet.lock().unwrap().fuel;{let mut wallet=bank.wallet.lock().unwrap();wallet.work_error=Some(work_error);wallet.post_error=Some(receipt_error)}assert!(!bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut terminal,&mut observe).unwrap());assert!(handoff.has_refused_receipt_action());assert_eq!(handoff.work_refusal().unwrap().message.as_ptr(),work_pointer);
 let mut original=PaidAction::default();original.begin_handoff_initial(&mut bank,&mut handoff,&mut observe);let mut completion=None;original.stage_handoff_original(&mut bank,&mut handoff,&mut completion);assert_eq!(original.post_handoff(&mut bank,&mut handoff,&mut observe),OriginalConstructionAcceptStatus::Accepted);original.publish_handoff_completion(&mut bank,&mut handoff,&mut completion,&mut observe);assert_eq!(completion.as_ref().unwrap().refusal().unwrap().message.as_ptr(),receipt_pointer);original.finish_handoff(&mut bank,&mut handoff,&mut observe);
 let retry_error=ValueError::new(ValueRefusalKind::OwnershipLimit,String::from("independent payout refusal"));let retry_pointer=retry_error.message.as_ptr();let mut primary=PaidAction::default();primary.begin_handoff_primary(&mut bank,&mut handoff,completion.as_ref().unwrap(),&mut observe);primary.stage_handoff_primary(&mut bank,&mut handoff,&mut completion);bank.wallet.lock().unwrap().post_error=Some(retry_error);bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||primary.post_handoff(&mut bank,&mut handoff,&mut observe)));assert!(interrupted.is_err());assert_eq!(primary.post_handoff(&mut bank,&mut handoff,&mut observe),OriginalConstructionAcceptStatus::Refused);primary.finish_handoff_work(&mut bank,&mut handoff,&mut observe);
 let mut capture=PaidAction::default();capture.begin_handoff_capture(&mut bank,&mut handoff,primary.physical.as_ref().unwrap(),&mut observe);let mut refusal=None;capture.stage_handoff_capture(&mut bank,&mut handoff,&mut primary.physical,&mut refusal);assert_eq!(capture.post_handoff(&mut bank,&mut handoff,&mut observe),OriginalConstructionAcceptStatus::Accepted);capture.publish_handoff_completion(&mut bank,&mut handoff,&mut refusal,&mut observe);assert_eq!(refusal.as_ref().unwrap().refusal().unwrap().message.as_ptr(),retry_pointer);capture.finish_handoff(&mut bank,&mut handoff,&mut observe);bank.with_terminal_loans(|work,physical|handoff.restore_receipt_retry(refusal.as_ref().unwrap(),work,physical)).unwrap();
 let mut retry=PaidAction::default();retry.begin_handoff_retry(&mut bank,&mut handoff,refusal.as_ref().unwrap(),&mut observe);retry.stage_handoff_retry(&mut bank,&mut handoff,refusal.as_ref().unwrap());assert_eq!(retry.post_handoff(&mut bank,&mut handoff,&mut observe),OriginalConstructionAcceptStatus::Accepted);retry.publish_handoff_primary(&mut bank,&mut handoff,&mut observe);retry.finish_handoff(&mut bank,&mut handoff,&mut observe);assert_eq!(handoff.post_refusal().unwrap().message.as_ptr(),receipt_pointer);assert_eq!(handoff.work_refusal().unwrap().message.as_ptr(),work_pointer);
 let before_denial=bank.wallet.lock().unwrap().fuel;bank.wallet.lock().unwrap().deny=true;assert!(!retirement.transfer(&mut bank,&mut handoff,&mut observe));assert_eq!(bank.wallet.lock().unwrap().fuel,before_denial);assert_eq!(handoff.post_refusal().unwrap().message.as_ptr(),receipt_pointer);bank.wallet.lock().unwrap().deny=false;for _ in 0..16{if retirement.transfer(&mut bank,&mut handoff,&mut observe){break}}let failure=retirement.failure().expect("actual terminal failure published");assert_eq!(failure.work_refusal.as_ref().unwrap().message.as_ptr(),work_pointer);assert_eq!(failure.receipt_completion().unwrap().message.as_ptr(),receipt_pointer);for _ in 0..16{if bank.finish_frame(&mut handoff,&mut frame,&mut recipient,&mut terminal,&mut observe).unwrap(){break}}assert_eq!(terminal.ledger_identity(),Some(ledger));
 let(actual_before_release,fixed_before,fixed_tail)={let(frame,recipient)=terminal.owners_mut().unwrap();let mut release=PaidAction::default();release.begin_guarded(&mut bank,frame,recipient,None,retirement.release_demand().unwrap(),1,&mut observe);release.retire_terminal_receipt(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(release.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release.finish(&mut bank,frame,recipient,&mut observe);let mut release=PaidAction::default();release.begin(&mut bank,frame,recipient,None,refusal.as_ref().unwrap().release_demand(),&mut observe);release.retire(&mut bank,frame,&mut refusal,false);assert_eq!(release.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release.finish(&mut bank,frame,recipient,&mut observe);
 let fixed_before=stock["copyBytes"].as_u64().unwrap() as usize-bank.wallet.lock().unwrap().left.maximum_copy_bytes;for _ in 0..stock["retirementCycles"].as_u64().unwrap(){if retirement.empty(){break}let (cycle_items,cycle_fuel)={let wallet=bank.wallet.lock().unwrap();(wallet.left.maximum_items,wallet.fuel)};if retirement.needs_birth(){retirement.birth(&mut bank,frame,recipient,&mut observe);let wallet=bank.wallet.lock().unwrap();assert!(cycle_items-wallet.left.maximum_items<=stock["itemsPerCycle"].as_u64().unwrap() as usize);assert!(cycle_fuel-wallet.fuel<=u128::from(stock["workPerCycle"].as_u64().unwrap()));continue}let demand=retirement.demand();let work=retirement.work();let cycle_copy=demand.copy_bytes.checked_add(PaidAction::retirement_reply_demand().copy_bytes).and_then(|n|n.checked_add(PaidAction::reply_release_demand().copy_bytes)).unwrap();assert!(cycle_copy<=stock["copyBytesPerCycle"].as_u64().unwrap() as usize);assert!(demand.capacity_bytes<=stock["capacityBytesPerCycle"].as_u64().unwrap() as usize);assert!(demand.depth<=stock["depth"].as_u64().unwrap() as usize);assert!(u128::from(work)+2<=u128::from(stock["workPerCycle"].as_u64().unwrap()));let mut operation=PaidAction::default();operation.begin_guarded(&mut bank,frame,recipient,None,demand,work,&mut observe);let mut ready=false;for _ in 0..32{if operation.retirement_producer(&mut bank,frame,recipient,&mut retirement,&mut observe){ready=true;break}}assert!(ready,"original retirement reply remains pending");let status=operation.post_optional(&mut bank,frame,recipient,&mut observe);assert!(status.is_none()||status==Some(OriginalConstructionAcceptStatus::Accepted));operation.finish(&mut bank,frame,recipient,&mut observe);let mut transfer=PaidAction::default();transfer.begin_guarded(&mut bank,frame,recipient,None,PaidAction::retirement_reply_demand(),1,&mut observe);transfer.transfer_retirement_reply(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(transfer.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);transfer.finish(&mut bank,frame,recipient,&mut observe);retirement.finish_action();assert!(retirement.reply().is_some());;let wallet=bank.wallet.lock().unwrap();assert!(cycle_items-wallet.left.maximum_items<=stock["itemsPerCycle"].as_u64().unwrap() as usize);assert!(cycle_fuel-wallet.fuel<=u128::from(stock["workPerCycle"].as_u64().unwrap()))}assert!(retirement.empty(),"original failure retirement remains live");let mut release=PaidAction::default();release.begin_guarded(&mut bank,frame,recipient,None,PaidAction::reply_release_demand(),1,&mut observe);release.release_retirement_reply(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(release.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release.finish(&mut bank,frame,recipient,&mut observe);let cycle_end_copy=bank.wallet.lock().unwrap().left.maximum_copy_bytes;
 let mut release=PaidAction::default();release.begin_guarded(&mut bank,frame,recipient,None,PaidAction::controlled_release_demand(),1,&mut observe);release.release_controlled(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(release.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release.finish(&mut bank,frame,recipient,&mut observe);let mut transfer=PaidAction::default();transfer.begin_guarded(&mut bank,frame,recipient,None,retirement_actor::Actor::producer_demand(),1,&mut observe);transfer.transfer_retirement_producer(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(transfer.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);transfer.finish(&mut bank,frame,recipient,&mut observe);let mut release=PaidAction::default();release.begin_guarded(&mut bank,frame,recipient,None,PaidAction::producer_release_demand(),1,&mut observe);release.release_retirement_producer(&mut bank,frame,recipient,&mut retirement,&mut observe);assert_eq!(release.post(&mut bank,frame,recipient,&mut observe),OriginalConstructionAcceptStatus::Accepted);release.finish(&mut bank,frame,recipient,&mut observe);assert!(retirement.finished());let fixed_tail=cycle_end_copy-bank.wallet.lock().unwrap().left.maximum_copy_bytes;(frame.actual_work(),fixed_before,fixed_tail)};drop(retirement);assert!(failure_slot.is_none());let before_terminal_retirement=bank.wallet.lock().unwrap().left.maximum_copy_bytes;for _ in 0..16{if bank.retire_frame_output(&mut handoff,&mut terminal,&mut observe).unwrap(){break}}assert!(handoff.is_empty());let wallet=bank.wallet.lock().unwrap();let fixed_total=fixed_before+fixed_tail+(before_terminal_retirement-wallet.left.maximum_copy_bytes);assert!(fixed_total<=stock["fixedCopyReserve"].as_u64().unwrap() as usize);assert_eq!(stock["items"].as_u64().unwrap() as usize-wallet.left.maximum_items,wallet.spent.copied_items);assert_eq!(stock["copyBytes"].as_u64().unwrap() as usize-wallet.left.maximum_copy_bytes,wallet.spent.copied_bytes);assert_eq!(stock["capacityBytes"].as_u64().unwrap() as usize-wallet.left.maximum_capacity_bytes,wallet.spent.retained_capacity_bytes);assert_eq!(stock["releaseBytes"].as_u64().unwrap() as usize-wallet.left.maximum_release_bytes,wallet.spent.released_bytes);assert_eq!(before-wallet.fuel,actual_before_release+1);
}
